import { createAudioPlayer } from 'expo-audio';
import { createFeedbackSounds, type SoundName } from './feedbackSound';

/** Generated by scripts/make-sounds.cjs: no third-party rights. */
const SOURCES: Record<SoundName, number> = {
  'success-pop': require('../../assets/sounds/success-pop.wav'),
  'success-chime': require('../../assets/sounds/success-chime.wav'),
  'success-marimba': require('../../assets/sounds/success-marimba.wav'),
  'error-thud': require('../../assets/sounds/error-thud.wav'),
  'error-soft': require('../../assets/sounds/error-soft.wav'),
  'error-glide': require('../../assets/sounds/error-glide.wav'),
  'unit-complete': require('../../assets/sounds/unit-complete.wav'),
  'level-up': require('../../assets/sounds/level-up.wav'),
};

/**
 * The default audio mode is kept on purpose: the sounds follow the phone's silent switch and mix
 * with other audio instead of interrupting it.
 */
export const feedbackSounds = createFeedbackSounds((name) => createAudioPlayer(SOURCES[name]));
